Lemma map_blk_iv_lbrm : forall LBb blk A,
  (forall b', In b' LBb -> aptr_eqb (blk_slot b') (blk_slot blk) = (blk_addr b' =? A)) ->
  map blk_iv (lbrm LBb blk) = List.filter (fun b => negb (fst b =? A)) (map blk_iv LBb).
Proof.
